UPDATE food_daily_visit v
INNER JOIN app_user u ON u.id = v.user_id
SET v.visited_at = CURRENT_TIMESTAMP
WHERE v.food_id = #{foodId}
  AND u.username = #{username}
  AND v.visit_date = CURRENT_DATE

UPDATE food
SET heat = heat + 1
WHERE id = #{id}
